$pt=static fn(string $source):string=>\Kulturhus\Native\Language\FinancePreferenceMessages::text($source,$preferenceMessages);$pv=static fn(mixed $value):string=>is_string($value)||is_int($value)?(string)$value:(is_bool($value)?($value?'1':'0'):(is_array($value)?GeneralRequests::json($value):''));$pkeep=[];foreach(['preference_draft','preference_receipt','preference_history_q','preference_history_page','preference_revisions_page','preference_revision','preference_year','preference_query','preference_page','preference_selected_page']as$key)if(is_string($_GET[$key]??null))$pkeep[$key]=$_GET[$key];$purl=static fn(array $query=[]):string=>url(['view'=>'settings','section'=>'finance_preferences']+array_replace($pkeep,$query));
