$preview=static function(array $review)use($pt,$pvalues):void{?><h4><?= e($pt('Damals gelesener Stand')) ?> · <?= e($review['current']['version']) ?></h4><?php $pvalues($review['current']['data']);?><h4><?= e($pt('Vollständige gewünschte Eingaben')) ?></h4><?php $pvalues($review['input']['data']);?><h4><?= e($pt('Nach Bestätigung gespeicherte Werte')) ?></h4><?php $pvalues($review['normalized']);foreach($review['preference_context']as$year=>$source):?><details class="general-settings-values"><summary><?= e($pt('Damals geprüfte tatsächliche Konten')) ?> <?= e($year) ?></summary><?php foreach($source['selected']as$row):?><article class="general-settings-row"><p><strong><?= e($row['code']) ?> · <?= e($row['name']) ?></strong></p><p><?= e($pt(TaxCatalog::GROUPS[$row['category']]??$row['category'])) ?> · <?= e($pt($row['active']?'Aktiv':'Inaktiv')) ?></p><pre><?= e(GeneralRequests::json($row)) ?></pre></article><?php endforeach ?></details><?php endforeach; };
$ppages=static function(?array $page,string $field)use($pt,$pv,$phidden):void{if(!$page)return;?><form method="get" class="general-settings-page-form"><?= $phidden([$field]) ?><label class="general-settings-field"><?= e($pt('Seite')) ?><input class="form-control" name="<?= e($field) ?>" value="<?= e($pv($page['page_input'])) ?>" inputmode="numeric"></label><button class="btn btn-outline theme-secondary"><?= e($pt('Seite öffnen')) ?></button><span><?= e($page['total']) ?> · <?= e($page['pages']) ?></span></form><?php };
